import{_ as t,o as a,c as i,ao as s}from"./chunks/framework.BnY313mr.js";const o="/BeamletOptics.jl/previews/PR64/assets/agb_doubleslit_experiment.B2BB5Ltq.png",h=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"examples/double_slit.md","filePath":"examples/double_slit.md","lastUpdated":null}'),l={name:"examples/double_slit.md"};function r(n,e,c,p,m,d){return a(),i("div",null,[...e[0]||(e[0]=[s('<h2 id="Double-slit-diffraction" tabindex="-1">Double slit diffraction <a class="header-anchor" href="#Double-slit-diffraction" aria-label="Permalink to &quot;Double slit diffraction {#Double-slit-diffraction}&quot;">​</a></h2><p>One of the most powerful applications of the beamlet tracing method is the simulation of coherent diffraction from complex apertures. The <strong>BMO</strong> package provides the <a href="/BeamletOptics.jl/previews/PR64/reference#BeamletOptics.AstigmaticGaussianBeamlet"><code>AstigmaticGaussianBeamlet</code></a> as an implementation of this formalism. More information can be found in the <a href="/BeamletOptics.jl/previews/PR64/basics/beams/astigmatic_beam#Astigmatic-polarized-beamlets">Astigmatic polarized beamlets</a> section. By using a <a href="/BeamletOptics.jl/previews/PR64/reference#BeamletOptics.WavefrontBeamletDecomposition-Union{Tuple{L}, Tuple{D}, Tuple{Ph}, Tuple{A}, Tuple{P2}, Tuple{P1}, Tuple{AbstractVector{P1}, AbstractVector{P2}, AbstractMatrix{A}, AbstractMatrix{Ph}, AbstractArray{D}, L}} where {P1&lt;:Real, P2&lt;:Real, A&lt;:Real, Ph&lt;:Real, D&lt;:Real, L&lt;:Real}"><code>WavefrontBeamletDecomposition</code></a>, any arbitrary aperture mask (including phase-varying masks) can be decomposed into a set of coherent beamlets.</p><p>In the example below, a classic double-slit mask (10 µm width, 100 µm separation) is decomposed and propagated 0.2 meters. The simulation perfectly reproduces the analytical Fraunhofer diffraction pattern, showcasing both the individual slit diffraction (envelope) and the coherent interference fringes.</p><p><img src="'+o+'" alt=""></p><p>This example demonstrates the package&#39;s ability to maintain phase coherence across thousands of beamlets. This is, in principle, a prerequisite for high-fidelity modeling of systems like Atmospheric Turbulence or Phase-Modulating SLMs.</p>',5)])])}const u=t(l,[["render",r]]);export{h as __pageData,u as default};
